<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from "vue";
import { useQuery } from "@tanstack/vue-query";
import * as echarts from "echarts";
import { AlertCircle, BarChart3, LoaderCircle, RotateCw } from "lucide-vue-next";
import { getDashboard } from "../../api/analytics";
import { ACTION_CODES, ACTION_LABELS } from "../../shared/types/action";
const dataset = ref(""); const channel = ref(""); const language = ref(""); const action = ref(""); const scoreElement = ref<HTMLElement>(); const actionElement = ref<HTMLElement>(); let scoreChart: echarts.ECharts | null = null; let actionChart: echarts.ECharts | null = null;
const params = computed(() => { const p = new URLSearchParams(); if (dataset.value) p.set("datasetGroupId", dataset.value); if (channel.value) p.set("channel", channel.value); if (language.value) p.set("language", language.value); if (action.value) p.set("action", action.value); return p; });
const query = useQuery({ queryKey: computed(() => ["analytics", params.value.toString()]), queryFn: ({ signal }) => getDashboard(params.value, signal) });
watch([() => query.data.value, scoreElement, actionElement], async ([data]) => { if (!data) return; await nextTick(); if (scoreElement.value) { scoreChart ??= echarts.init(scoreElement.value); scoreChart.setOption({ tooltip: {}, xAxis: { type: "category", data: data.score_distribution.map(x => x.label) }, yAxis: { type: "value", minInterval: 1 }, series: [{ type: "bar", data: data.score_distribution.map(x => x.count), itemStyle: { color: "#f14646", borderRadius: [6,6,0,0] } }] }); } if (actionElement.value) { actionChart ??= echarts.init(actionElement.value); const entries = Object.entries(data.actions); actionChart.setOption({ tooltip: { trigger: "item" }, legend: { bottom: 0 }, series: [{ type: "pie", radius: ["38%", "68%"], data: entries.map(([name, value]) => ({ name: ACTION_LABELS[name as keyof typeof ACTION_LABELS] ?? name, value })) }] }); } }, { immediate: true });
onBeforeUnmount(() => { scoreChart?.dispose(); actionChart?.dispose(); });
const cards = computed(() => query.data.value ? [{ label: "Conversations", value: query.data.value.totals.conversations }, { label: "Analyzed", value: query.data.value.totals.analyzed }, { label: "Average score", value: query.data.value.totals.average_score === null ? "—" : `${query.data.value.totals.average_score}%` }, { label: "Severe violations", value: query.data.value.totals.severe_violations }, { label: "Pending appeals", value: query.data.value.appeals.pending }, { label: "Avg. operator response", value: query.data.value.totals.average_operator_response_ms === null ? "—" : `${Math.round(query.data.value.totals.average_operator_response_ms / 1000)}s` }] : []);
</script>
<template><section><div class="flex items-start gap-3"><div class="grid size-12 place-items-center rounded-2xl bg-primary-soft text-primary"><BarChart3 /></div><div><h1 class="text-2xl font-black">Analytics dashboard</h1><p class="mt-1 text-sm text-muted">Live metrics calculated from stored conversations, evaluations, classifications, metadata, and appeals.</p></div></div><div class="mt-6 grid gap-3 rounded-2xl bg-white p-4 sm:grid-cols-4"><input v-model="dataset" class="field" placeholder="Dataset group" /><select v-model="channel" class="field"><option value="">All channels</option><option value="chat">Chat</option><option value="call">Voice call</option></select><select v-model="language" class="field"><option value="">All languages</option><option value="ru">RU</option><option value="kk">KZ</option><option value="en">EN</option></select><select v-model="action" class="field"><option value="">All actions</option><option v-for="code in ACTION_CODES" :key="code" :value="code">{{ ACTION_LABELS[code] }}</option></select></div><div v-if="query.isLoading.value" class="mt-6 flex justify-center gap-2 rounded-2xl bg-white p-12 text-muted"><LoaderCircle class="animate-spin" /> Loading analytics…</div><div v-else-if="query.isError.value" class="mt-6 rounded-2xl bg-white p-10 text-center text-red-700"><AlertCircle class="mx-auto" /><p class="mt-3">{{ query.error.value?.message }}</p><button class="button-secondary mt-4" @click="query.refetch()"><RotateCw :size="16" /> Retry</button></div><div v-else-if="query.data.value"><div class="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div v-for="card in cards" :key="card.label" class="rounded-2xl bg-white p-5"><p class="text-xs font-bold uppercase text-muted">{{ card.label }}</p><p class="mt-2 text-3xl font-black">{{ card.value }}</p></div></div><div v-if="!query.data.value.totals.conversations" class="mt-6 rounded-2xl bg-white p-12 text-center text-muted">No conversations match these filters.</div><div v-else class="mt-6 grid gap-6 lg:grid-cols-2"><div class="rounded-2xl bg-white p-5"><h2 class="font-bold">Quality-score distribution</h2><div ref="scoreElement" class="mt-3 h-72" /></div><div class="rounded-2xl bg-white p-5"><h2 class="font-bold">Primary recommended actions</h2><div ref="actionElement" class="mt-3 h-72" /></div><div class="rounded-2xl bg-white p-5"><h2 class="font-bold">Resolution</h2><p class="mt-4 text-sm">Resolved <strong>{{ query.data.value.resolution.resolved }}</strong> · Unresolved <strong>{{ query.data.value.resolution.unresolved }}</strong></p><h3 class="mt-5 text-sm font-bold">Languages</h3><p class="mt-2 text-sm text-muted">RU {{ query.data.value.languages.ru ?? 0 }} · KZ {{ query.data.value.languages.kk ?? 0 }} · EN {{ query.data.value.languages.en ?? 0 }}</p><h3 class="mt-5 text-sm font-bold">Channel</h3><p class="mt-2 text-sm text-muted">Chat {{ query.data.value.channels.chat ?? 0 }} · Voice {{ query.data.value.channels.call ?? 0 }}</p></div><div class="rounded-2xl bg-white p-5"><h2 class="font-bold">Operations</h2><h3 class="mt-4 text-sm font-bold">Review outcomes</h3><p class="mt-2 text-sm text-muted">Confirmed {{ query.data.value.appeals.outcomes.CONFIRMED ?? 0 }} · Overridden {{ query.data.value.appeals.outcomes.OVERRIDDEN ?? 0 }}</p><h3 class="mt-5 text-sm font-bold">Evaluation processing</h3><div class="mt-2 flex flex-wrap gap-2"><span v-for="(value, status) in query.data.value.processing" :key="status" class="rounded-full bg-surface px-3 py-1.5 text-xs font-semibold capitalize">{{ status }} {{ value }}</span></div></div></div></div></section></template>
